import{_ as o,o as t,c as i,a3 as n}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"Credit Notes — Production Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Credit Notes — Production Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/credit-notes"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Credit Notes — Production Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/credit-notes"}]]},"headers":[],"relativePath":"deployment/credit-notes.md","filePath":"deployment/credit-notes.md","lastUpdated":1786636213000}'),s={name:"deployment/credit-notes.md"};function r(d,e,c,a,l,m){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="credit-notes-—-production-guide" tabindex="-1">Credit Notes — Production Guide <a class="header-anchor" href="#credit-notes-—-production-guide" aria-label="Permalink to &quot;Credit Notes — Production Guide&quot;">​</a></h1><h2 id="licensing" tabindex="-1">Licensing <a class="header-anchor" href="#licensing" aria-label="Permalink to &quot;Licensing&quot;">​</a></h2><ul><li>Catalog slug: <code>credit-notes</code></li><li>Category: <strong>Billing</strong> (<code>billing</code>)</li><li><strong>Free Marketplace opt-in</strong> (not auto-installed)</li><li>Catalog flags: <code>is_default_included = false</code>, <code>is_billable = false</code>, price <code>0</code>, <code>sort_order = 30</code></li><li><strong>Hard dependency on Invoices</strong> — declares a required <code>module_dependencies</code> row on <code>invoices</code>; Marketplace blocks installing Credit Notes on a workspace that doesn&#39;t already have Invoices entitled</li></ul><h2 id="bootstrap" tabindex="-1">Bootstrap <a class="header-anchor" href="#bootstrap" aria-label="Permalink to &quot;Bootstrap&quot;">​</a></h2><p>On <strong>new workspace</strong> create:</p><ol><li><code>installDefaultModules()</code> installs published <code>is_default_included</code> modules only (Credit Notes is never auto-installed)</li><li>Operators must enable <strong>Invoices</strong> before Credit Notes becomes installable from Marketplace</li><li>Tenant permissions include <code>credit-notes.*</code> via <code>config/tenant-permissions.php</code> / default role maps</li></ol><h2 id="permissions-rollout" tabindex="-1">Permissions rollout <a class="header-anchor" href="#permissions-rollout" aria-label="Permalink to &quot;Permissions rollout&quot;">​</a></h2><p>New Credit Notes permissions for <strong>existing</strong> workspaces ship as an additive <strong>data migration</strong> using <code>TenantPermissionSynchronizer::grantMissingDefaultRolePermissions([...])</code> (see <code>database/migrations/2026_07_31_222005_add_credit_notes_permissions.php</code>). Do <strong>not</strong> re-seed roles.</p><h2 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h2><ul><li>Platform audit events: <code>customer_credit_note_created</code>, <code>customer_credit_note_updated</code>, <code>customer_credit_note_deleted</code>, <code>customer_credit_note_assigned</code>, <code>customer_credit_note_status_changed</code>, <code>customer_credit_note_note_added</code></li><li>Notifications: assignment via <code>CustomerCreditNoteAssignedNotification</code></li><li>Issuing/applying/voiding a credit note updates the linked <code>CustomerInvoice</code> balance synchronously in the same request — no queued job to monitor</li></ul><h2 id="deploy-checklist" tabindex="-1">Deploy checklist <a class="header-anchor" href="#deploy-checklist" aria-label="Permalink to &quot;Deploy checklist&quot;">​</a></h2><ol><li>Migrate tables (<code>customer_credit_notes</code>, <code>customer_credit_note_lines</code>, <code>customer_credit_note_notes</code>, <code>customer_credit_note_activities</code>)</li><li>Register the <code>credit-notes</code> catalog module via migration (<code>DefaultModuleRegistrar</code>) as free Billing opt-in — <strong>not</strong> <code>db:seed</code></li><li>Run the <code>module_dependencies</code> migration that links <code>credit-notes</code> → <code>invoices</code> (required)</li><li>Run the credit notes permissions migration so default roles receive missing <code>credit-notes.*</code> grants</li><li>Confirm <code>module:credit-notes</code> + <code>credit-notes.*</code> permissions on target roles</li><li>Deploy Frontend SPA with Credit Notes nav (Billing sidebar group, after Payments) — verify a workspace <strong>without</strong> Invoices installed cannot install Credit Notes from Marketplace</li><li>Verify applying a credit note correctly increases the linked invoice&#39;s <code>amount_credited</code> and reduces <code>balance_due</code>, in a staging smoke test before rollout</li></ol>',12)])])}const p=o(s,[["render",r]]);export{g as __pageData,p as default};
